sys_script_include.script:
var CheckDuplicateEnrollment = Class.create();
CheckDuplicateEnrollment.prototype = Object.extendsObject(AbstractAjaxProcessor,{
    checkEnrollment: function() {
        var trainingID = this.getParameter('sysparm_training'); // Pega o curso selecionado
        var trainingDate = this.getParameter('sysparm_date'); // Pega a data do curso
        var userId = this.getParameter('sysparm_user'); // Pega o ID do usuário logado

        var enrollment = new GlideRecord('x_1593185_traini_0_training_enrollment');
        enrollment.addQuery('training_name', trainingID);
        enrollment.addQuery('training_date', trainingDate);
        enrollment.addQuery('opened_by', userId);
        enrollment.query();

        if (enrollment.next()) {
            return 'duplicate'; // Retorna "duplicate" se já existir a matrícula
        }

        return 'ok'; // Permite a matrícula se não houver duplicidade
    },

    type: 'CheckDuplicateEnrollment'
});
